# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: test-ledger.ps1

$LEDGER          = "http://localhost:8007"
$API_GATEWAY     = "http://localhost:8080"
$AUTH_SERVICE    = "http://localhost:9000"
$SECRET_KEY      = "sk_test_123"
$PUBLISHABLE_KEY = "pk_test_123"

$script:pass = 0
$script:fail = 0
$script:PAYMENT_ID = $null

# ── Helpers ──────────────────────────────────────────────────────────────────
# FIX 1: removed inner braces — param() block followed directly by statements
function Write-Header {
    param([string]$t)
    Write-Host "`n$("="*70)" -ForegroundColor Cyan
    Write-Host "  $t"        -ForegroundColor Cyan
    Write-Host "$("="*70)"   -ForegroundColor Cyan
}

function Write-Step {
    param([string]$t)
    Write-Host "`n  ► $t" -ForegroundColor Yellow
}

function Pass {
    param([string]$t)
    Write-Host "    ✓ $t" -ForegroundColor Green
    $script:pass++
}

function Fail {
    param([string]$t, [string]$e = "")
    Write-Host "    ✗ $t" -ForegroundColor Red
    if ($e) { Write-Host "      $e" -ForegroundColor DarkRed }
    $script:fail++
}

function Info {
    param([string]$t)
    Write-Host "      $t" -ForegroundColor White
}

# ─────────────────────────────────────────────────────────────────────────────

Clear-Host
Write-Host "`n╔$("═"*68)╗" -ForegroundColor Cyan
Write-Host "║$(" "*20)LEDGER SERVICE - COMPLETE TEST$(" "*18)║" -ForegroundColor Cyan
Write-Host "╚$("═"*68)╝" -ForegroundColor Cyan

# ── TEST 1: HEALTH ────────────────────────────────────────────────────────────
Write-Header "TEST 1: HEALTH CHECK"
try {
    $h = Invoke-RestMethod -Uri "$LEDGER/health" -Method GET
    if ($h.status -eq "ok") { Pass "Ledger Service healthy" }
    else { Fail "Unhealthy" }
} catch { Fail "Unreachable" "$_"; exit 1 }

# ── TEST 2: STATS ─────────────────────────────────────────────────────────────
Write-Header "TEST 2: SYSTEM ACCOUNTS & STATS"
try {
    $stats = Invoke-RestMethod -Uri "$LEDGER/stats" -Method GET
    Pass "Stats retrieved"
    Info "Total Entries      : $($stats.total_entries)"
    Info "Total Transactions : $($stats.total_transactions)"
    Info "Total Accounts     : $($stats.total_accounts)"
    Info "Platform Fee       : $($stats.platform_fee_percent)%"
    Info "Escrow Account     : $($stats.system_accounts.escrow)"
    Info "Fee Account        : $($stats.system_accounts.fees)"
} catch { Fail "Stats failed" "$_" }

# ── TEST 3: LIST ACCOUNTS ─────────────────────────────────────────────────────
Write-Header "TEST 3: LIST SYSTEM ACCOUNTS"
try {
    $accounts = Invoke-RestMethod -Uri "$LEDGER/accounts?owner_type=platform" -Method GET
    Pass "Accounts retrieved"
    Info "Total System Accounts: $($accounts.total)"
    foreach ($a in $accounts.accounts) {
        Info "  [$($a.id)] balance=$($a.balance) type=$($a.account_type)"
    }
} catch { Fail "List accounts failed" "$_" }

# ── TEST 4: RECORD AUTHORIZATION ─────────────────────────────────────────────
Write-Header "TEST 4: RECORD AUTHORIZATION DIRECTLY"
$testPaymentId = "pi_ledger_test_$(Get-Date -Format 'yyyyMMddHHmmss')"
try {
    $authRecord = Invoke-RestMethod -Uri "$LEDGER/record/authorization" `
        -Method POST -ContentType "application/json" `
        -Body (@{
            payment_id  = $testPaymentId
            merchant_id = "m_123"
            amount      = 10000
            currency    = "usd"
        } | ConvertTo-Json)
    Pass "Authorization recorded in ledger"
    Info "Transaction ID : $($authRecord.transaction_id)"
    Info "Event          : $($authRecord.event)"
    Info "Amount         : `$$($authRecord.amount)"
    Info "Status         : $($authRecord.status)"
} catch { Fail "Authorization record failed" "$_" }

# ── TEST 5: RECORD CAPTURE ────────────────────────────────────────────────────
Write-Header "TEST 5: RECORD CAPTURE DIRECTLY"
try {
    $captureRecord = Invoke-RestMethod -Uri "$LEDGER/record/capture" `
        -Method POST -ContentType "application/json" `
        -Body (@{
            payment_id  = $testPaymentId
            merchant_id = "m_123"
            amount      = 10000
            currency    = "usd"
        } | ConvertTo-Json)
    Pass "Capture recorded in ledger"
    Info "Transaction ID : $($captureRecord.transaction_id)"
    Info "Gross Amount   : `$$($captureRecord.gross_amount)"
    Info "Platform Fee   : `$$($captureRecord.platform_fee)"
    Info "Merchant Net   : `$$($captureRecord.merchant_net)"
} catch { Fail "Capture record failed" "$_" }

# ── TEST 6: RECORD REFUND ─────────────────────────────────────────────────────
Write-Header "TEST 6: RECORD REFUND DIRECTLY"
try {
    $refundRecord = Invoke-RestMethod -Uri "$LEDGER/record/refund" `
        -Method POST -ContentType "application/json" `
        -Body (@{
            payment_id  = $testPaymentId
            merchant_id = "m_123"
            amount      = 3000
            currency    = "usd"
            reason      = "customer_request"
        } | ConvertTo-Json)
    Pass "Refund recorded in ledger"
    Info "Transaction ID : $($refundRecord.transaction_id)"
    Info "Amount         : `$$($refundRecord.amount)"
    Info "Event          : $($refundRecord.event)"
} catch { Fail "Refund record failed" "$_" }

# ── TEST 7: RECORD VOID ───────────────────────────────────────────────────────
Write-Header "TEST 7: RECORD VOID DIRECTLY"
$voidPaymentId = "pi_void_test_$(Get-Date -Format 'yyyyMMddHHmmss')"
try {
    Invoke-RestMethod -Uri "$LEDGER/record/authorization" `
        -Method POST -ContentType "application/json" `
        -Body (@{
            payment_id  = $voidPaymentId
            merchant_id = "m_123"
            amount      = 5000
            currency    = "usd"
        } | ConvertTo-Json) | Out-Null

    $voidRecord = Invoke-RestMethod -Uri "$LEDGER/record/void" `
        -Method POST -ContentType "application/json" `
        -Body (@{
            payment_id  = $voidPaymentId
            merchant_id = "m_123"
            amount      = 5000
            currency    = "usd"
        } | ConvertTo-Json)
    Pass "Void recorded in ledger"
    Info "Transaction ID : $($voidRecord.transaction_id)"
    Info "Amount         : `$$($voidRecord.amount)"
    Info "Event          : $($voidRecord.event)"
} catch { Fail "Void record failed" "$_" }

# ── TEST 8: AUDIT TRAIL ───────────────────────────────────────────────────────
Write-Header "TEST 8: GET PAYMENT ENTRIES - AUDIT TRAIL"
try {
    $entries = Invoke-RestMethod -Uri "$LEDGER/entries/payment/$testPaymentId" -Method GET
    Pass "Payment entries retrieved"
    Info "Total Entries : $($entries.total_entries)"
    Info "Transactions  : $($entries.transactions.Count)"
    Write-Host "`n      Money Trail:" -ForegroundColor Cyan
    foreach ($tx in $entries.transactions) {
        Write-Host "        [$($tx.event_type)] amount=`$$($tx.amount) status=$($tx.status)" -ForegroundColor White
    }
    Write-Host "`n      Ledger Entries:" -ForegroundColor Cyan
    foreach ($e in $entries.entries) {
        $color = if ($e.entry_type -eq "debit") { "Green" } else { "Red" }
        Write-Host "        [$($e.entry_type.ToUpper())] $($e.account_id) amount=`$$($e.amount) balance_after=`$$($e.balance_after)" -ForegroundColor $color
    }
} catch { Fail "Payment entries failed" "$_" }

# ── TEST 9: MERCHANT BALANCE ──────────────────────────────────────────────────
Write-Header "TEST 9: GET MERCHANT BALANCE"
try {
    $balance = Invoke-RestMethod -Uri "$LEDGER/balance/merchant/m_123" -Method GET
    Pass "Merchant balance retrieved"
    Info "Merchant ID        : $($balance.merchant_id)"
    Info "Available Balance  : `$$($balance.available_balance)"
    Info "Pending Balance    : `$$($balance.pending_balance)"
    Info "Total Balance      : `$$($balance.total_balance)"
    Info "Total Earned       : `$$($balance.total_earned)"
    Info "Total Fees Paid    : `$$($balance.total_fees_paid)"
    Info "Total Refunded     : `$$($balance.total_refunded)"
} catch { Fail "Merchant balance failed" "$_" }

# ── TEST 10: PLATFORM SUMMARY ─────────────────────────────────────────────────
Write-Header "TEST 10: GET PLATFORM SUMMARY"
try {
    $platform = Invoke-RestMethod -Uri "$LEDGER/balance/platform" -Method GET
    Pass "Platform summary retrieved"
    Info "Total Volume   : `$$($platform.total_volume)"
    Info "Total Fees     : `$$($platform.total_fees)"
    Info "Escrow Balance : `$$($platform.escrow_balance)"
    Info "Total Refunds  : `$$($platform.total_refunds)"
    Info "Net Revenue    : `$$($platform.net_revenue)"
} catch { Fail "Platform summary failed" "$_" }

# ── TEST 11: RECONCILIATION ───────────────────────────────────────────────────
Write-Header "TEST 11: RECONCILIATION CHECK"
try {
    $reconcile = Invoke-RestMethod -Uri "$LEDGER/reconcile/$testPaymentId" -Method GET
    if ($reconcile.is_balanced) {
        Pass "Payment is balanced"
        Info "Total Debits  : `$$($reconcile.total_debits)"
        Info "Total Credits : `$$($reconcile.total_credits)"
        Info "Difference    : `$$($reconcile.difference)"
        Info "Status        : $($reconcile.status)"
        Info "Events        : $($reconcile.events_recorded -join ', ')"
    } else {
        Fail "UNBALANCED - data integrity problem!"
        Info "Debits  : $($reconcile.total_debits)"
        Info "Credits : $($reconcile.total_credits)"
        Info "Diff    : $($reconcile.difference)"
    }
} catch { Fail "Reconciliation failed" "$_" }

# ── TEST 12: FULL MERCHANT FLOW ───────────────────────────────────────────────
Write-Header "TEST 12: FULL FLOW - MERCHANT PAYMENT AUTO-RECORDS TO LEDGER"

Write-Step "Create merchant payment"
try {
    $mHeaders = @{
        "Content-Type"    = "application/json"
        "Authorization"   = "Bearer $SECRET_KEY"
        "Idempotency-Key" = "ledger_test_$(Get-Date -Format 'yyyyMMddHHmmss')"
    }
    $mPayment = Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $mHeaders `
        -Body (@{
            amount      = 15000
            currency    = "usd"
            customer    = @{ email="merchant@example.com"; name="Test Merchant" }
            card        = @{ number="4242424242424242"; exp_month=12; exp_year=2026; cvc="123" }
            description = "Ledger integration test"
            capture     = $false
        } | ConvertTo-Json)

    $script:PAYMENT_ID = $mPayment.payment_id
    Pass "Merchant payment authorized"
    Info "Payment ID : $($mPayment.payment_id)"
    Info "Status     : $($mPayment.status)"

    Start-Sleep -Seconds 3

    Write-Step "Check ledger received authorization"
    try {
        $ledgerEntries = Invoke-RestMethod `
            -Uri "$LEDGER/entries/payment/$($mPayment.payment_id)" -Method GET
        if ($ledgerEntries.total_entries -gt 0) {
            Pass "Ledger auto-updated after authorization"
            Info "Entries: $($ledgerEntries.total_entries)"
        } else {
            Fail "Ledger not updated - check LEDGER_SERVICE_URL in payment-service"
        }
    } catch { Fail "Could not check ledger entries" "$_" }

} catch {
    Fail "Merchant payment failed" "$($_.ErrorDetails.Message)"
}

Write-Step "Capture payment"
try {
    # FIX: omit amount entirely instead of sending null — avoids JSON null validation errors
    $captureBody = @{ payment_id = $script:PAYMENT_ID } | ConvertTo-Json

    $captureResult = Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/captures" `
        -Method POST -ContentType "application/json" `
        -Headers @{ "Authorization" = "Bearer $SECRET_KEY" } `
        -Body $captureBody

    Pass "Payment captured"
    Info "Status   : $($captureResult.status)"
    Info "Captured : `$$($captureResult.captured_amount / 100)"

    Start-Sleep -Seconds 3

    Write-Step "Check merchant balance updated after capture"
    $balanceAfterCapture = Invoke-RestMethod -Uri "$LEDGER/balance/merchant/m_123" -Method GET
    Pass "Merchant balance updated"
    Info "Available Balance : `$$($balanceAfterCapture.available_balance)"
    Info "Total Earned      : `$$($balanceAfterCapture.total_earned)"
    Info "Fees Paid         : `$$($balanceAfterCapture.total_fees_paid)"

} catch {
    Fail "Capture/balance check failed" "$($_.ErrorDetails.Message)"
}

# ── TEST 13: FULL CUSTOMER FLOW ───────────────────────────────────────────────
Write-Header "TEST 13: FULL CUSTOMER FLOW → LEDGER UPDATED"

Write-Step "Get JWT"
try {
    $jwt = (Invoke-RestMethod -Uri "$AUTH_SERVICE/token" -Method POST -ContentType "application/json" `
        -Body (@{
            sub    = "cust_ledger_$(Get-Date -Format 'yyyyMMddHHmmss')"
            email  = "customer@gmail.com"
            roles  = @("customer")
            scopes = @("payment_session:create","payment_method:tokenize","payment_intent:confirm_own")
        } | ConvertTo-Json)).access_token
    Pass "JWT obtained"
} catch { Fail "JWT failed" "$_"; return }

$cHeaders = @{
    "Content-Type"      = "application/json"
    "X-Publishable-Key" = $PUBLISHABLE_KEY
    "Authorization"     = "Bearer $jwt"
}

# FIX 2: added cart_id
# FIX 3: wrapped in try/catch — failure here skips confirm gracefully
Write-Step "Create session"
try {
    $session = Invoke-RestMethod -Uri "$API_GATEWAY/v1/customer/payment_sessions" `
        -Method POST -Headers $cHeaders `
        -Body (@{
            amount      = 5000
            currency    = "usd"
            description = "Ledger test"
            capture     = $true
            cart_id     = "cart_ledger_$(Get-Date -Format 'yyyyMMddHHmmss')"
        } | ConvertTo-Json)
    Pass "Session created: $($session.session_id)"
} catch { Fail "Session creation failed" "$($_.ErrorDetails.Message)"; return }

Write-Step "Tokenize Mastercard"
try {
    $token = Invoke-RestMethod -Uri "$API_GATEWAY/v1/customer/payment_methods/tokenize" `
        -Method POST -Headers $cHeaders `
        -Body (@{ card_number="5555555555554444"; exp_month=12; exp_year=2026; cvc="123" } | ConvertTo-Json)
    Pass "Card tokenized: $($token.payment_method_token)"
} catch { Fail "Tokenize failed" "$($_.ErrorDetails.Message)"; return }

Write-Step "Confirm payment"
try {
    $payment = Invoke-RestMethod -Uri "$API_GATEWAY/v1/customer/payment_intents/confirm" `
        -Method POST -Headers $cHeaders `
        -Body (@{
            session_id           = $session.session_id
            payment_method_token = $token.payment_method_token
        } | ConvertTo-Json)

    Pass "Customer payment confirmed!"
    Info "Payment ID : $($payment.payment.payment_id)"
    Info "Status     : $($payment.payment.status)"

    Start-Sleep -Seconds 3

    Write-Step "Verify ledger updated"
    $custLedger = Invoke-RestMethod -Uri "$LEDGER/entries/payment/$($payment.payment.payment_id)" -Method GET

    if ($custLedger.total_entries -gt 0) {
        Pass "Ledger updated for customer payment"
        Info "Entries: $($custLedger.total_entries)"
        Info "Events : $($custLedger.transactions | ForEach-Object { $_.event_type })"
    } else {
        Fail "Ledger not updated for customer payment"
    }
} catch {
    $rawErr = $_.ErrorDetails.Message
    Fail "Customer payment failed"
    try {
        $e = $rawErr | ConvertFrom-Json
        Info "Code: $($e.detail.code) | Msg: $($e.detail.message)"
        if ($e.detail.code -eq "fraud_detected") {
            Info "Fix: docker exec postgres psql -U payments -d fraud_db -c 'TRUNCATE fraud_checks, ml_training_samples CASCADE;'"
        }
    } catch { Info "Raw error: $rawErr" }
}

# ── FINAL SUMMARY ─────────────────────────────────────────────────────────────
Write-Host "`n╔$("═"*68)╗" -ForegroundColor Cyan
Write-Host "║$(" "*25)FINAL RESULTS$(" "*30)║" -ForegroundColor Cyan
Write-Host "╚$("═"*68)╝" -ForegroundColor Cyan

Write-Host "`n  Total  : $($script:pass + $script:fail)" -ForegroundColor White
Write-Host "  Passed : $($script:pass)" -ForegroundColor Green
Write-Host "  Failed : $($script:fail)" -ForegroundColor Red

if ($script:fail -eq 0) {
    Write-Host "`n  ✓ ALL LEDGER TESTS PASSED!"          -ForegroundColor Green
    Write-Host "  ✓ Every dollar is tracked!"            -ForegroundColor Green
    Write-Host "  ✓ Double-entry bookkeeping working!"   -ForegroundColor Green
    Write-Host "  ✓ Merchant balances updating!"         -ForegroundColor Green
    Write-Host "  ✓ Platform fees being collected!"      -ForegroundColor Green
} else {
    Write-Host "`n  ⚠ $($script:fail) TEST(S) FAILED"                             -ForegroundColor Yellow
    Write-Host "  Logs: docker-compose logs --tail=20 ledger-service"  -ForegroundColor Gray
    Write-Host "  Logs: docker-compose logs --tail=20 payment-service" -ForegroundColor Gray
}
Write-Host ""
